"""Klasifikasi risiko aksi: LOW, MEDIUM, HIGH. HIGH wajib konfirmasi user."""

HIGH_KEYWORDS = (
    "hapus", "delete", "format", "kirim pesan", "kirim email",
    "install software", "registry", "shutdown", "password",
)

# ponytail: pencocokan keyword sederhana, ganti classifier LLM saat pola aksi bertambah
def classify(action, args):
    name = (action or "").lower()
    blob = " ".join(str(v).lower() for v in (args or {}).values())
    if name in ("delete_file", "send_message", "install_software",
                 "run_shell", "system_config"):
        return "HIGH"
    if any(k in blob for k in HIGH_KEYWORDS):
        return "HIGH"
    if name in ("open_app", "open_url", "screenshot", "search_web"):
        return "LOW"
    return "MEDIUM"


def needs_confirm(action, args, confirmed=False):
    return classify(action, args) == "HIGH" and not confirmed

"""Klien DeepSeek (OpenAI-compatible) dengan urllib stdlib. Tanpa pip install."""
import json
import urllib.request

API_URL = "https://api.deepseek.com/chat/completions"
SYSTEM = ("Kamu perencana aksi untuk agen desktop Windows. Jawab HANYA JSON: "
          '{"steps": [{"tool": "open_app|type_text|click|open_url|screenshot", '
          '"args": {}, "risk": "LOW|MEDIUM|HIGH"}]}. '
          "Maksimal 4 langkah. Jangan sertakan teks lain.")


def plan(message, api_key, model="deepseek-flash", timeout=40):
    body = json.dumps({
        "model": model,
        "messages": [{"role": "system", "content": SYSTEM},
                     {"role": "user", "content": message}],
        "temperature": 0.2,
        "max_tokens": 600,
    }).encode("utf-8")
    req = urllib.request.Request(API_URL, data=body, headers={
        "Content-Type": "application/json",
        "Authorization": "Bearer " + api_key,
    })
    try:
        with urllib.request.urlopen(req, timeout=timeout) as res:
            payload = json.loads(res.read().decode("utf-8"))
    except Exception as e:
        raise RuntimeError("LLM tidak terjangkau: %s" % e)
    try:
        text = payload["choices"][0]["message"]["content"]
        return json.loads(text)["steps"]
    except (KeyError, ValueError, TypeError):
        raise RuntimeError("respon LLM bukan JSON rencana yang valid")

"""Agent loop: UNDERSTAND -> PLAN -> RISK CHECK -> EXECUTE -> OBSERVE -> VERIFY."""
from . import llm
from tools import actions, permissions

MAX_RETRY = 2
STATUS = ["Memahami perintah...", "Membuat rencana...", "Menjalankan tindakan...",
          "Mengamati hasil...", "Memverifikasi...", "Selesai."]

RUNNERS = {
    "open_app": lambda a: actions.open_app(a.get("app", "")),
    "type_text": lambda a: actions.type_text(a.get("text", "")),
    "click": lambda a: actions.click(a.get("x"), a.get("y")),
    "open_url": lambda a: actions.open_url(a.get("url", "")),
    "screenshot": lambda a: "tersimpan: " + actions.screenshot(),
}


def heuristic_plan(message):
    """Perencana lokal tanpa API. Menangani perintah demo Fase 1."""
    m = (message or "").lower()
    if "screenshot" in m:
        return [{"tool": "screenshot", "args": {}, "risk": "LOW"}]
    if "notepad" in m:
        steps = [{"tool": "open_app", "args": {"app": "notepad"}, "risk": "LOW"}]
        if "ketik" in m or "type" in m or "halo" in m or "hello" in m:
            steps.append({"tool": "type_text",
                          "args": {"text": _after_keyword(message)}, "risk": "MEDIUM"})
        return steps
    if "browser" in m or "cari" in m or "search" in m:
        q = _after_keyword(message) or "AI agent"
        return [{"tool": "open_url",
                 "args": {"url": "https://duckduckgo.com/?q=" + q.replace(" ", "+")},
                 "risk": "LOW"}]
    if "kalkulator" in m or "calc" in m:
        return [{"tool": "open_app", "args": {"app": "calc"}, "risk": "LOW"}]
    return []


def _after_keyword(message):
    for kw in ("ketik", "type", "cari", "search"):
        if kw in message.lower():
            return message.lower().split(kw, 1)[1].strip().strip("\"'") or "Halo Dunia"
    if "halo" in message.lower() or "hello" in message.lower():
        return "Halo Dunia"
    return ""


def run_step(tool, args):
    if tool not in RUNNERS:
        raise ValueError("tool '%s' belum didukung di Fase 1" % tool)
    return RUNNERS[tool](args or {})


def handle(message, api_key=None, confirmed=None):
    """Jalankan satu perintah. Return dict {reply, steps, needs_confirm, pending}."""
    steps_log = [STATUS[0]]
    plan_steps = heuristic_plan(message)
    if not plan_steps and api_key:
        steps_log.append(STATUS[1] + " (cloud)")
        plan_steps = llm.plan(message, api_key)
    elif plan_steps:
        steps_log.append(STATUS[1] + " (lokal)")
    if not plan_steps:
        return {"reply": ("Aku belum paham perintah itu di mode offline. "
                           "Isi DEEPSEEK_API_KEY untuk perintah bebas, atau coba: "
                           "Buka Notepad, Screenshot, Buka browser."),
                "steps": steps_log, "needs_confirm": False, "pending": None}
    for i, s in enumerate(plan_steps):
        tool, args = s.get("tool", ""), s.get("args", {})
        risk = permissions.classify(tool, args)
        if permissions.needs_confirm(tool, args, confirmed == i):
            return {"reply": "Aksi '%s' berisiko %s dan butuh persetujuanmu." % (tool, risk),
                    "steps": steps_log + [STATUS[2] + " menunggu konfirmasi"],
                    "needs_confirm": True,
                    "pending": {"tool": tool, "args": args, "step": i}}
        ok, err = False, ""
        for _ in range(MAX_RETRY + 1):
            try:
                result = run_step(tool, args)
                ok = True
                break
            except Exception as e:
                err = str(e)
        if not ok:
            return {"reply": "Langkah '%s' gagal: %s" % (tool, err),
                    "steps": steps_log + [STATUS[2], STATUS[3], "Verifikasi gagal."],
                    "needs_confirm": False, "pending": None}
        steps_log.append("%s -> %s" % (tool, result))
    steps_log += [STATUS[3], STATUS[4], STATUS[5]]
    return {"reply": "Selesai. %d langkah berjalan." % len(plan_steps),
            "steps": steps_log, "needs_confirm": False, "pending": None}

"""Backend Fase 1: HTTP server stdlib. Sajikan frontend + API chat/act/history/health."""
import json
import os
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

import sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from agent import core
from tools import actions, permissions

ROOT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
HISTORY = []


def log(*parts):
    print("[INFO]", *parts, flush=True)


def load_env():
    for name in (os.path.join(ROOT, "config", ".env"),
                 os.path.join(ROOT, ".env")):
        if not os.path.exists(name):
            continue
        with open(name, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#") and "=" in line:
                    k, v = line.split("=", 1)
                    os.environ.setdefault(k.strip(), v.strip().strip("\"'"))


def history_add(action, result):
    HISTORY.append({"time": time.strftime("%H:%M:%S"), "action": action,
                    "result": result[:120]})
    del HISTORY[:-50]


class Handler(BaseHTTPRequestHandler):
    server_version = "FlashAI/1"

    def _json(self, obj, code=200):
        data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def _body(self):
        try:
            return json.loads(self.rfile.read(
                int(self.headers.get("Content-Length", 0) or 0)).decode("utf-8") or "{}")
        except (ValueError, KeyError):
            return {}

    def do_GET(self):
        path = urlparse(self.path).path
        if path in ("/", "/index.html"):
            return self._file(os.path.join(ROOT, "frontend", "index.html"), "text/html")
        if path == "/api/health":
            key = os.environ.get("DEEPSEEK_API_KEY", "")
            return self._json({"ok": True, "bridge": "on",
                               "llm": "deepseek-flash" if key else "belum dikonfigurasi"})
        if path == "/api/history":
            return self._json({"items": HISTORY})
        self._json({"error": "tidak dikenal"}, 404)

    def do_POST(self):
        path = urlparse(self.path).path
        if path == "/api/chat":
            msg = self._body().get("message", "")
            log("User command received:", msg[:80])
            try:
                out = core.handle(msg, os.environ.get("DEEPSEEK_API_KEY", ""))
            except Exception as e:
                out = {"reply": "Gagal: %s" % e, "steps": [], "needs_confirm": False}
            log("Task completed:", out["reply"][:80])
            return self._json(out)
        if path == "/api/act":
            b = self._body()
            tool, args = b.get("action", ""), {k: v for k, v in b.items()
                                               if k not in ("action", "confirm")}
            if permissions.needs_confirm(tool, args, b.get("confirm")):
                return self._json({"needs_confirm": True,
                                   "message": "Aksi HIGH butuh konfirmasi."})
            try:
                result = core.run_step(tool, args)
                history_add(tool, result)
                log("Action executed:", tool, "->", result[:80])
                return self._json({"message": "OK: " + result})
            except Exception as e:
                return self._json({"message": "Gagal: %s" % e})
        self._json({"error": "tidak dikenal"}, 404)

    def _file(self, path, ctype):
        try:
            with open(path, "rb") as f:
                data = f.read()
        except OSError:
            return self._json({"error": "tidak dikenal"}, 404)
        self.send_response(200)
        self.send_header("Content-Type", ctype + "; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, *a):
        pass


if __name__ == "__main__":
    load_env()
    port = int(os.environ.get("PORT", "8787"))
    log("Agent started on port", port)
    ThreadingHTTPServer(("127.0.0.1", port), Handler).serve_forever()

