"""Backend Fase 1: HTTP server stdlib. Sajikan frontend + API chat/act/history/health."""
import json
import os
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

import sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from agent import core
from tools import actions, permissions

ROOT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
HISTORY = []
HISTORY_FILE = os.path.join(ROOT, "data", "history.jsonl")


def log(*parts):
    print("[INFO]", *parts, flush=True)


def load_env():
    for name in (os.path.join(ROOT, "config", ".env"),
                 os.path.join(ROOT, ".env")):
        if not os.path.exists(name):
            continue
        with open(name, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#") and "=" in line:
                    k, v = line.split("=", 1)
                    os.environ.setdefault(k.strip(), v.strip().strip("\"'"))


def history_add(action, result):
    entry = {"time": time.strftime("%Y-%m-%d %H:%M:%S"), "action": action,
             "result": result[:120]}
    HISTORY.append(entry)
    del HISTORY[:-50]
    try:
        os.makedirs(os.path.dirname(HISTORY_FILE), exist_ok=True)
        with open(HISTORY_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    except OSError:
        pass


def history_load():
    try:
        with open(HISTORY_FILE, encoding="utf-8") as f:
            for line in f:
                try:
                    HISTORY.append(json.loads(line))
                except ValueError:
                    pass
        del HISTORY[:-50]
    except OSError:
        pass


class Handler(BaseHTTPRequestHandler):
    server_version = "FlashAI/1"

    def _json(self, obj, code=200):
        data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def _body(self):
        try:
            return json.loads(self.rfile.read(
                int(self.headers.get("Content-Length", 0) or 0)).decode("utf-8") or "{}")
        except (ValueError, KeyError):
            return {}

    def do_GET(self):
        path = urlparse(self.path).path
        if path in ("/", "/index.html"):
            return self._file(os.path.join(ROOT, "frontend", "index.html"), "text/html")
        if path == "/api/health":
            key = os.environ.get("DEEPSEEK_API_KEY", "")
            return self._json({"ok": True, "bridge": "on",
                               "llm": "deepseek-flash" if key else "belum dikonfigurasi"})
        if path == "/api/history":
            return self._json({"items": HISTORY})
        self._json({"error": "tidak dikenal"}, 404)

    def do_POST(self):
        path = urlparse(self.path).path
        if path == "/api/chat":
            b = self._body()
            log("User command received:", b.get("message", "")[:80])
            try:
                out = core.handle(b.get("message", ""),
                                  os.environ.get("DEEPSEEK_API_KEY", ""),
                                  b.get("confirmed_step"),
                                  b.get("resume"))
                for s in out.get("steps", []):
                    if " -> " in s:
                        history_add(s.split(" -> ", 1)[0], s.split(" -> ", 1)[1])
            except Exception as e:
                out = {"reply": "Gagal: %s" % e, "steps": [], "needs_confirm": False}
            log("Task completed:", out["reply"][:80])
            return self._json(out)
        if path == "/api/act":
            b = self._body()
            tool, args = b.get("action", ""), {k: v for k, v in b.items()
                                               if k not in ("action", "confirm")}
            if (permissions.needs_confirm(tool, args, b.get("confirm")) or
                    (core._outside_data(args) and not b.get("confirm"))):
                return self._json({"needs_confirm": True,
                                   "message": "Aksi HIGH butuh konfirmasi."})
            try:
                result = core.run_step(tool, args)
                history_add(tool, result)
                log("Action executed:", tool, "->", result[:80])
                return self._json({"message": "OK: " + result})
            except Exception as e:
                return self._json({"message": "Gagal: %s" % e})
        self._json({"error": "tidak dikenal"}, 404)

    def _file(self, path, ctype):
        try:
            with open(path, "rb") as f:
                data = f.read()
        except OSError:
            return self._json({"error": "tidak dikenal"}, 404)
        self.send_response(200)
        self.send_header("Content-Type", ctype + "; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, *a):
        pass


if __name__ == "__main__":
    load_env()
    history_load()
    port = int(os.environ.get("PORT", "8787"))
    log("Agent started on port", port)
    ThreadingHTTPServer(("127.0.0.1", port), Handler).serve_forever()

