def screenshot():
    """Simpan screenshot ke data/shot-<waktu>.png. Return path atau raise."""
    out = os.path.join(_data_dir(),
                       "shot-" + datetime.now().strftime("%Y%m%d-%H%M%S") + ".png")
    ps = ("Add-Type -AssemblyName System.Windows.Forms,System.Drawing;"
          "$b = New-Object Drawing.Bitmap([Windows.Forms.Screen]::PrimaryScreen.Bounds.Width,"
          "[Windows.Forms.Screen]::PrimaryScreen.Bounds.Height);"
          "$g = [Drawing.Graphics]::FromImage($b);"
          "$g.CopyFromScreen(0,0,0,0,$b.Size);$g.Dispose();"
          "$b.Save('%s');$b.Dispose()" % out.replace("'", "''"))
    r = subprocess.run(["powershell", "-NoProfile", "-Command", ps],
                       capture_output=True, text=True, timeout=30)
    if r.returncode != 0 or not os.path.exists(out):
        raise RuntimeError("screenshot gagal: " + (r.stderr or "unknown")[:200])
    return out


