"""Environment scan: aplikasi apa yang tersedia di komputer ini.
Hasil: data/environment.json. Stdlib saja."""
import json
import os
import shutil
import subprocess

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.normpath(os.path.join(HERE, ".."))
OUT = os.path.join(ROOT, "data", "environment.json")

CANDIDATES = {
    "winword": ("Microsoft Word", ["document_creation", "text_editing"]),
    "excel": ("Microsoft Excel", ["spreadsheet", "table_data"]),
    "powerpnt": ("Microsoft PowerPoint", ["presentation"]),
    "chrome": ("Google Chrome", ["browser"]),
    "msedge": ("Microsoft Edge", ["browser"]),
    "firefox": ("Firefox", ["browser"]),
    "code": ("VS Code", ["code_editor"]),
    "notepad": ("Notepad", ["text_editing"]),
    "calc": ("Kalkulator", ["calculator"]),
}


def _which(prog):
    if shutil.which(prog):
        return True
    try:
        r = subprocess.run(["where", prog], capture_output=True,
                           text=True, timeout=10)
        return r.returncode == 0
    except OSError:
        return False


def _app_paths(prog):
    import winreg
    try:
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                            r"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\%s.exe" % prog) as k:
            return winreg.QueryValue(k, None) or True
    except OSError:
        return False


def scan():
    apps = []
    for prog, (label, caps) in CANDIDATES.items():
        found = _which(prog + ".exe") or _app_paths(prog)
        if found:
            apps.append({"name": label, "program": prog, "capabilities": caps})
    try:
        py = subprocess.run(["py", "--version"], capture_output=True,
                            text=True, timeout=10)
        python = (py.stdout or py.stderr or "").strip()
    except OSError:
        python = ""
    env = {"applications": apps, "python": python,
           "internet": True}
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8") as f:
        f.write(json.dumps(env, ensure_ascii=False, indent=1))
    return env


def load():
    try:
        with open(OUT, encoding="utf-8") as f:
            return json.loads(f.read() or "{}")
    except (OSError, ValueError):
        return {"applications": []}


def summary():
    env = load() or {"applications": []}
    names = [a["name"] for a in env.get("applications", [])]
    if not names:
        return "belum ada hasil scan. Aplikasi umum diasumsikan ada."
    return "Terinstall: " + ", ".join(names) + "."


if __name__ == "__main__":
    print(json.dumps(scan(), ensure_ascii=False, indent=1))

"""Capability registry: intent -> provider + tool. Intent dulu, aplikasi kemudian."""
from . import environment

CAPABILITIES = {
    "document_creation": {
        "providers": ["Microsoft Word", "Notepad"],
        "tools": ["create_docx", "open_file", "type_text"],
        "hint": "buat .docx lalu buka dengan aplikasi dokumen yang ada",
    },
    "spreadsheet": {
        "providers": ["Microsoft Excel"],
        "tools": ["create_xlsx", "open_file"],
        "hint": "buat .xlsx lalu buka dengan aplikasi spreadsheet yang ada",
    },
    "browser": {
        "providers": ["Google Chrome", "Microsoft Edge", "Firefox"],
        "tools": ["open_browser", "open_url", "web_fetch", "web_search"],
        "hint": "pakai browser default yang tersedia",
    },
    "file_management": {
        "providers": [],
        "tools": ["list_dir", "make_dir", "move_file", "rename_file",
                  "read_file", "create_file", "delete_file"],
        "hint": "operasi langsung di dalam folder data",
    },
    "shell": {
        "providers": [],
        "tools": ["run_shell"],
        "hint": "perintah Windows, konfirmasi hanya untuk hapus/berbahaya",
    },
    "research": {
        "providers": [],
        "tools": ["research", "web_search", "web_fetch"],
        "hint": "cari, baca, ringkas dengan sumber",
    },
}


def available(capability):
    """Provider terinstall untuk capability ini (kosong = tool bawaan)."""
    env = environment.load()
    have = {a["name"] for a in env.get("applications", [])}
    return [p for p in CAPABILITIES[capability]["providers"] if p in have]


def describe():
    lines = []
    for cap, spec in CAPABILITIES.items():
        prov = available(cap)
        who = ", ".join(prov) if prov else "tool bawaan"
        lines.append("- %s: %s (%s)" % (cap, ", ".join(spec["tools"]), who))
    missing = [c for c in ("document_creation", "spreadsheet", "browser")
               if not available(c)]
    if missing:
        lines.append("Tidak tersedia: %s. Pilih alternatif yang ada dan "
                     "beri tahu user." % ", ".join(missing))
    return "\n".join(lines)

