:root{
  --bg:#0b0e14; --card:#141926; --line:#262f45; --acc:#4f7cff;
  --ghost:#202845; --txt:#e9edf6; --mut:#9aa3bd;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  background:var(--bg); color:var(--txt);
  font-family:"Segoe UI",system-ui,-apple-system,Arial,sans-serif;
  font-size:14.5px; line-height:1.6;
}
.wrap{max-width:720px;margin:0 auto;padding:12px 12px 24px}
header{display:flex;align-items:center;justify-content:space-between;gap:12px;
  padding:10px 2px;border-bottom:1px solid var(--line);margin-bottom:12px}
.logo{font-size:17px;font-weight:700;margin:0}
.status{font-size:13px;font-weight:600;border:1px solid var(--line);border-radius:8px;
  padding:8px 12px;min-height:44px;display:inline-flex;align-items:center;background:var(--card)}
.status.on{color:var(--acc);border-color:var(--acc)}
.status.off{color:var(--mut)}
#chat{background:var(--card);border:1px solid var(--line);border-radius:12px;
  min-height:280px;max-height:52vh;overflow-y:auto;padding:12px}
.msg{margin:0 0 10px;padding:8px 10px;border-radius:8px;background:var(--bg);
  border:1px solid var(--line);overflow-wrap:break-word}
.msg.me{border-color:var(--acc)}
.msg .who{font-size:12px;color:var(--mut);margin-bottom:2px}
.msg ul{margin:6px 0 2px;padding-left:20px}
.msg ol.steps{margin:6px 0 2px;padding-left:22px}
.msg ol.steps li{margin-bottom:6px}
.msg ol.steps li.st{list-style:none;margin-left:-22px;color:var(--mut)}
.msg img{max-width:100%;border:1px solid var(--line);border-radius:8px;margin-top:6px}
.empty{color:var(--mut)}
.empty code{font-family:Consolas,"Courier New",monospace;font-size:13px;color:var(--txt)}
.typing{color:var(--mut);font-style:italic}
.error{border:1px solid #b04a4a;background:#1d1216;border-radius:8px;padding:8px 10px;margin:0 0 10px}
.row{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}
button{
  font:inherit;color:var(--txt);background:var(--ghost);
  border:1px solid var(--line);border-radius:8px;
  min-height:44px;padding:10px 14px;cursor:pointer;
}
button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid var(--acc);outline-offset:2px}
button.primary{background:var(--acc);color:#0b0e14;font-weight:700;border-color:var(--acc)}
button:disabled{opacity:.55;cursor:not-allowed}
.chips button{border-radius:8px}
form.send{display:flex;gap:8px;margin-top:4px;align-items:flex-end}
textarea{flex:1;min-width:0;font:inherit;color:var(--txt);background:var(--bg);
  border:1px solid var(--line);border-radius:8px;min-height:44px;padding:10px 12px;
  resize:none;line-height:1.6}
details.pad{border:1px solid var(--line);border-radius:12px;background:var(--card);
  padding:4px 12px 12px;margin:12px 0}

