async function health(){
  try{
    var ctl=new AbortController(),to=setTimeout(function(){ctl.abort();},5000);
    var r=await fetch("/api/health",{cache:"no-store",signal:ctl.signal});
    clearTimeout(to);
    var j=await r.json();
    var txt=document.getElementById("bridgeTxt");
    if(j&&j.ok){txt.textContent="Bridge: ON";bridge.className="status on";}
    else{txt.textContent="Bridge: OFF";bridge.className="status off";}
  }catch(e){
    document.getElementById("bridgeTxt").textContent="Bridge: OFF";
    bridge.className="status off";
  }
}

