def _focus_exe(exe):
    """SetForegroundWindow ke jendela utama pertama milik exe."""
    u = ctypes.windll.user32
    psapi = ctypes.windll.psapi
    found = []

    @ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
    def cb(hwnd, _):
        if not u.IsWindowVisible(hwnd):
            return True
        if u.GetWindowTextLengthW(hwnd) == 0:
            return True
        pid = ctypes.c_ulong()
        u.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        h = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid.value)
        if h:
            buf = ctypes.create_unicode_buffer(260)
            if psapi.GetModuleBaseNameW(h, None, buf, 260):
                if buf.value.lower() == exe.lower():
                    found.append(hwnd)
                    ctypes.windll.kernel32.CloseHandle(h)
                    return False
            ctypes.windll.kernel32.CloseHandle(h)
        return True

    try:
        u.EnumWindows(cb, None)
    except (OSError, ValueError):
        return False
    if not found:
        return False
    time.sleep(0.3)
    return bool(u.SetForegroundWindow(found[0]))

