async function send(text){
  if(!text) return;
  setLast(text);
  add("Kamu",esc(text),"me");
  var t=add("Agen",'<span class="typing">Memahami perintah...</span>');
  btnStop.disabled=false;
  ctl=new AbortController();
  var live=setInterval(async function(){
    try{
      var pr=await fetch("/api/progress",{cache:"no-store",signal:ctl.signal});
      var pj=await pr.json();
      if(pj&&(pj.steps||[]).length){
        var d=document.createElement("div");
        renderSteps(d,pj.steps);
        t.lastChild.innerHTML='<span class="typing">Menjalankan...</span>';
        t.lastChild.appendChild(d);
      }
    }catch(e){}
  },2000);
  try{
    var r=await fetch("/api/chat",{method:"POST",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify({message:text}),signal:ctl.signal});
    var j=await r.json();
    clearInterval(live);
    renderReply(t.lastChild,j,text);
  }catch(e){
    clearInterval(live);
    var msg=(e&&e.name==="AbortError")?"Dihentikan atas permintaanmu.":
      "Jaringan atau server bermasalah. Cek Start-Agent masih jalan, ganti key di file .env, atau coba hotspot lain.";
    t.lastChild.innerHTML='<div class="error">'+esc(msg)+'</div>';
  }
  btnStop.disabled=true; ctl=null;
}

