            subprocess.run(["taskkill", "/F", "/IM", exe],
                           capture_output=True, timeout=20)
            time.sleep(2.0)
            os.startfile(target)
            for _ in range(10):
                if _has_window(exe):
                    return
                time.sleep(1.0)
