    key = (app or "").strip().lower()
    if key not in ALLOW_APPS:
        if key in ("chrome", "browser", "edge", "firefox"):
            raise ValueError("untuk browser pakai perintah 'buka browser', bukan nama aplikasi")
        raise ValueError("aplikasi '%s' belum didukung. Bisa dibuka: Notepad, Kalkulator, Word, Excel, PowerPoint, Discord, WhatsApp, Telegram, Spotify." % app)
    exe = ALLOW_APPS[key]
    if key in APP_CMD:
        cmd, exe = APP_CMD[key]
        if not is_running(exe):
            subprocess.Popen(cmd)
            time.sleep(4.0)
    elif key in APP_START:
        if not is_running(exe):
            os.startfile(APP_START[key])
            time.sleep(2.5)
        for _ in range(8):
            if _has_window(exe):
                break
            if not is_running(exe):
                os.startfile(APP_START[key])
            time.sleep(1.0)
        if not _has_window(exe):
            subprocess.run(["taskkill", "/F", "/IM", exe],
                           capture_output=True, timeout=20)
            time.sleep(2.0)
            os.startfile(APP_START[key])
            for _ in range(10):
                if _has_window(exe):
                    break
                time.sleep(1.0)
    else:
        p = subprocess.Popen([exe])
        time.sleep(1.0)
        if p.poll() is not None and p.returncode != 0:
            raise RuntimeError("gagal membuka " + key)
        return "terbuka (pid %s)" % p.pid
    if not is_running(exe):
        raise RuntimeError("gagal membuka " + key)
    if key in APP_START and not _has_window(exe):
        raise RuntimeError("%s berjalan tapi tak menampilkan jendela. "
                           "Buka manual sekali lalu ulangi." % key)
    return "terbuka"

