async function send(text){
  if(!text) return;
  setLast(text);
  add("Kamu",esc(text),"me");
  var t=add("Agen",'<span class="typing">Memahami perintah...</span>');
  btnStop.disabled=false;
  ctl=new AbortController();
  var live=null,liveSteps=[],liveOk=false;
  function liveRender(){
    var d=document.createElement("div");
    renderSteps(d,liveSteps);
    t.lastChild.innerHTML='<span class="typing">Menjalankan...</span>';
    t.lastChild.appendChild(d);
  }
  try{
    live=new EventSource("/api/events");
    live.onmessage=function(e){
      try{
        liveSteps.push(JSON.parse(e.data));
        liveOk=true;liveRender();
      }catch(err){}
    };
    live.onerror=function(){if(live){live.close();live=null;}};
  }catch(e){live=null;}
  var poll=setInterval(async function(){
    if(liveOk)return;
    try{
      var pr=await fetch("/api/progress",{cache:"no-store",signal:ctl.signal});
      var pj=await pr.json();
      if(pj&&(pj.steps||[]).length){
        liveSteps=pj.steps;liveRender();
      }
    }catch(e){}
  },2000);
  try{
    var r=await fetch("/api/chat",{method:"POST",
