var convoId="",convoStamp="";
async function loadConvos(){
  var sel=document.getElementById("convoSel");
  try{
    var r=await fetch("/api/convos",{cache:"no-store"});var j=await r.json();
    var items=j.items||[];
    sel.innerHTML="";
    if(!items.length){
      var o=document.createElement("option");o.value="";o.textContent="(belum ada)";
      sel.appendChild(o);return;
    }
    items.sort(function(a,b){return (b.updated||"")<(a.updated||"")?-1:1;});
    items.forEach(function(c){
      var o=document.createElement("option");o.value=c.id;
      o.textContent=c.title+" ("+c.n+")";sel.appendChild(o);
    });
    if(!convoId||!items.some(function(c){return c.id===convoId;})){
      convoId=items[0].id;
    }
    sel.value=convoId;convoStamp="";
  }catch(e){}
}
async function loadConvo(announce){
  if(!convoId)return;
  try{
    var r=await fetch("/api/convo?id="+encodeURIComponent(convoId),{cache:"no-store"});
    var j=await r.json();
    if(j.error||j.updated===convoStamp)return;
    convoStamp=j.updated;
    chat.innerHTML="";log=[];
    (j.messages||[]).forEach(function(m){
      if(m.who==="Kamu"){add("Kamu",esc(m.text),"me");}
      else{
        var d=add("Agen","");
        d.lastChild.innerHTML="<p>"+esc(m.text||"")+"</p>";
        if(m.steps&&m.steps.length){
          var s=document.createElement("div");d.lastChild.appendChild(s);
          var keep=renderStepsHTML(m.steps);s.innerHTML=keep;
        }
      }
    });
    if(announce)add("Sistem","Percakapan dibuka: "+(j.title||""));
  }catch(e){}
}
function renderStepsHTML(steps){
  var d=document.createElement("div");renderSteps(d,steps||[]);
  return d.innerHTML;
}
document.getElementById("convoSel").addEventListener("change",function(e){
  convoId=e.target.value;loadConvo(true);
});
document.getElementById("btnNew").addEventListener("click",function(){
  convoId="";chat.innerHTML="";log=[];showEmpty();loadConvos();
});
document.getElementById("btnRename").addEventListener("click",async function(){
  if(!convoId)return;
  var t=prompt("Nama baru:",document.getElementById("convoSel").selectedOptions[0].text);
  if(!t)return;
  await fetch("/api/convos",{method:"POST",headers:{"Content-Type":"application/json"},
    body:JSON.stringify({action:"rename",id:convoId,title:t})});
  loadConvos();
});
document.getElementById("btnDel").addEventListener("click",async function(){
  if(!convoId||!confirm("Hapus percakapan ini dari semua perangkat?"))return;
  await fetch("/api/convos",{method:"POST",headers:{"Content-Type":"application/json"},
    body:JSON.stringify({action:"delete",id:convoId})});
  convoId="";chat.innerHTML="";log=[];showEmpty();loadConvos();
});
setInterval(function(){
  if(ctl||!convoId)return;
  loadConvo(false);
},5000);

