def do_GET(self):
    path = urlparse(self.path).path
    if path in ("/", "/index.html"):
        return self._file(os.path.join(ROOT, "frontend", "index.html"), "text/html")
    if path == "/api/health":
        key = os.environ.get("DEEPSEEK_API_KEY", "")
        return self._json({"ok": True, "bridge": "on",
                           "llm": "deepseek-flash" if key else "belum dikonfigurasi"})
    if path == "/api/history":
        return self._json({"items": HISTORY})
    if path == "/api/tasks":
        return self._json({"items": TASKS})
    if path == "/api/convos":
        return self._json({"items": [
            {"id": c["id"], "title": c.get("title", ""),
             "updated": c.get("updated", ""),
             "n": len(c.get("messages", []))} for c in CONVOS]})
    if path == "/api/convo":
        q = urlparse(self.path).query
        cid = ""
        for kv in q.split("&"):
            if kv.startswith("id="):
                cid = kv[3:]
        c = convo_get(cid)
        if c is None:
            return self._json({"error": "tidak ada"})
        return self._json(c)
    if path == "/api/progress":
        return self._json(PROGRESS)
    if path == "/api/events":
        return self._events()
    if path == "/api/shot":
        import re
        name = ""
        for kv in urlparse(self.path).query.split("&"):
            if kv.startswith("name="):
                name = kv[5:]
        if re.fullmatch(r"shot-\d{8}-\d{6}\.png", name or ""):
            return self._file(os.path.join(ROOT, "data", name), "image/png")
        return self._json({"error": "tidak dikenal"}, 404)
    if path == "/assets/AIbackground.jpg":
        return self._file(os.path.join(ROOT, "frontend", "assets",
                                       "AIbackground.jpg"), "image/jpeg")
    self._json({"error": "tidak dikenal"}, 404)

